/**
 * Jinx Leviathan + Sage: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Leviathan
 * Wiki: https://wiki.bloodontheclocktower.com/Sage
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`. Replace the `it.todo` with tests of the rule
 * the jinx imposes, where the engine can check it (for example a setup warning when only one
 * of the two may be in play). Paraphrase, never copy wiki prose.
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';

describe('Leviathan + Sage jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'leviathan', 'sage');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('leviathan')?.name).toBe('Leviathan');
		expect(data.byId.get('sage')?.name).toBe('Sage');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['leviathan', 'sage'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['leviathan'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['sage'])).not.toContain(jinx);
	});

	// Waits for a Demon night step (L112 left it): each night after the first the Demon picks
	// an alive good player, never the same twice, and a chosen partner acts as if killed.
	it.todo('enforces the rule the jinx imposes');
});
